param([Parameter(Mandatory=$true)][string]$TaskRoot,[Parameter(Mandatory=$true)][string]$SourceRoot,[Parameter(Mandatory=$true)][string]$PacketRoot)
$ErrorActionPreference='Stop'
$TaskRoot=[IO.Path]::GetFullPath($TaskRoot);$SourceRoot=[IO.Path]::GetFullPath($SourceRoot);$PacketRoot=[IO.Path]::GetFullPath($PacketRoot)
if(-not $SourceRoot.StartsWith($TaskRoot.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Source checkout is outside isolated task root.'}
if(-not $PacketRoot.StartsWith('C:\maos\review-packets\committed-install-gui-validation-2026-10-29',[StringComparison]::OrdinalIgnoreCase)){throw 'Evidence root is outside the authorized packet.'}
$commit='27dd1711f47e6278a1b84a6089e900dbe79f1459';$expectedDelta='d3b267f3e1032eb26b1e814876d4ab17ccd74df63bee62bab4ab27f6e7180622'
$head=( & git -C $SourceRoot rev-parse HEAD ).Trim();if($head -cne $commit){throw "Unexpected source commit $head"};if(Test-Path (Join-Path $SourceRoot '.npmrc')){throw 'Project .npmrc exists; refusing to use it.'}
$node=(Get-Command node.exe -ErrorAction Stop).Source;$npm=(Get-Command npm.cmd -ErrorAction Stop).Source;$git=(Get-Command git.exe -ErrorAction Stop).Source;$pwsh=(Get-Command powershell.exe -ErrorAction Stop).Source
$sys=$env:SystemRoot;$windir=$env:WINDIR;$arch=$env:PROCESSOR_ARCHITECTURE;$cpu=$env:NUMBER_OF_PROCESSORS;$nodeDir=Split-Path -Parent $node;$gitDir=Split-Path -Parent $git;$npmCli=Join-Path $nodeDir 'node_modules\npm\bin\npm-cli.js';if(-not(Test-Path -LiteralPath $npmCli)){throw "Pinned npm CLI not found beside Node: $npmCli"}
$buildHome=Join-Path $TaskRoot 'final build home with spaces';$temp=Join-Path $TaskRoot 'final build temp with spaces';$cache=Join-Path $TaskRoot 'final isolated npm cache';foreach($dir in @($buildHome,$temp,$cache)){if(Test-Path $dir){throw "Expected a fresh isolated path: $dir"};New-Item -ItemType Directory -Path $dir|Out-Null}
$userConfig=Join-Path $buildHome 'user.npmrc';$globalConfig=Join-Path $buildHome 'global.npmrc';$gitConfig=Join-Path $buildHome 'empty.gitconfig';Set-Content $userConfig '# empty isolated npm user config' -Encoding ascii;Set-Content $globalConfig '# empty isolated npm global config' -Encoding ascii;Set-Content $gitConfig '# empty isolated git config' -Encoding ascii
$nodeVersion=(& $node --version).Trim();$npmVersion=(& $npm --version).Trim()
foreach($name in @((Get-ChildItem Env:).Name)){Remove-Item -LiteralPath ('Env:'+$name) -ErrorAction SilentlyContinue}
$env:SystemRoot=$sys;$env:WINDIR=$windir;$env:OS='Windows_NT';$env:COMSPEC=Join-Path $sys 'System32\cmd.exe';$env:PATHEXT='.COM;.EXE;.BAT;.CMD';$env:PROCESSOR_ARCHITECTURE=$arch;$env:NUMBER_OF_PROCESSORS=$cpu;$env:PATH="$nodeDir;$gitDir;$sys\System32";$env:TEMP=$temp;$env:TMP=$temp;$env:USERPROFILE=$buildHome;$env:HOME=$buildHome;$env:APPDATA=Join-Path $buildHome 'AppData\Roaming';$env:LOCALAPPDATA=Join-Path $buildHome 'AppData\Local';New-Item -ItemType Directory -Path $env:APPDATA,$env:LOCALAPPDATA|Out-Null
$env:NPM_CONFIG_USERCONFIG=$userConfig;$env:NPM_CONFIG_GLOBALCONFIG=$globalConfig;$env:NPM_CONFIG_CACHE=$cache;$env:NPM_CONFIG_UPDATE_NOTIFIER='false';$env:NPM_CONFIG_AUDIT='false';$env:NPM_CONFIG_FUND='false';$env:GIT_CONFIG_GLOBAL=$gitConfig;$env:GIT_CONFIG_NOSYSTEM='1';$env:GIT_OPTIONAL_LOCKS='0'
function Quote([string]$v){'"'+$v.Replace('"','\"')+'"'}
function Run-Npm([string[]]$npmArgs,[string]$name){$stdout=Join-Path $PacketRoot ($name+'.stdout.log');$stderr=Join-Path $PacketRoot ($name+'.stderr.log');$log=Join-Path $PacketRoot ($name+'.log');$cmd='npm.cmd '+($npmArgs -join ' ');$cmd|Set-Content -LiteralPath (Join-Path $PacketRoot ($name+'.command.txt')) -Encoding utf8;$argsLine=((@($npmCli)+$npmArgs|ForEach-Object {Quote $_}) -join ' ');$proc=Start-Process -FilePath $node -ArgumentList $argsLine -WorkingDirectory $SourceRoot -NoNewWindow -Wait -PassThru -RedirectStandardOutput $stdout -RedirectStandardError $stderr;$exit=$proc.ExitCode;$out=if(Test-Path $stdout){Get-Content -LiteralPath $stdout -Raw}else{''};$err=if(Test-Path $stderr){Get-Content -LiteralPath $stderr -Raw}else{''};$combined=$out;if($err){$combined+="`n[stderr]`n"+$err};$combined|Set-Content -LiteralPath $log -Encoding utf8;"EXIT_CODE=$exit"|Add-Content -LiteralPath $log -Encoding utf8;if($exit -ne 0){throw "$cmd failed with exit $exit; see $log"};return $exit}
$ci=Run-Npm @('ci','--no-audit','--no-fund','--include=dev') 'source-npm-ci-final'
$build=Run-Npm @('run','build') 'source-npm-build-final'
$typecheck=Run-Npm @('run','typecheck:gui') 'source-gui-typecheck-final'
$tests=Run-Npm @('test','--','tests/cli/project-git-context.test.ts','tests/cli/doctor.test.ts','tests/cli/meta-provider-entrypoints.test.ts','tests/industrial/package-runtime-assets.test.ts') 'source-focused-tests-final'
$artifacts=Join-Path $PacketRoot 'candidate-artifacts';if(Test-Path $artifacts){throw 'Candidate artifacts already exist.'};New-Item -ItemType Directory -Path $artifacts|Out-Null
$pack=Run-Npm @('pack','--ignore-scripts','--pack-destination',$artifacts) 'npm-pack-final'
$archive=Get-ChildItem -LiteralPath $artifacts -Filter '*.tgz' -File|Select-Object -First 1;if(-not $archive){throw 'npm pack did not create a tarball.'}
$patch=Join-Path $PacketRoot 'committed-delta.patch';$patchHash=(Get-FileHash $patch -Algorithm SHA256).Hash.ToLowerInvariant();if($patchHash -cne $expectedDelta){throw "Commit patch hash mismatch: $patchHash"}
$bundle=Join-Path $artifacts 'maos-industrial-bootstrap-windows-x64-commit-27dd1711-2026-10-29.zip';$bundleScript=Join-Path $SourceRoot 'scripts\New-MaosIndustrialInstallBundle.ps1';$bundleArgs=@('-NoProfile','-ExecutionPolicy','Bypass','-File',$bundleScript,'-PackageArchive',$archive.FullName,'-SourceRevision',$commit,'-SourceDeltaSha256',$patchHash,'-OutputBundle',$bundle);$bundleLine=($bundleArgs|ForEach-Object {Quote $_}) -join ' ';$bundleLine|Set-Content -LiteralPath (Join-Path $PacketRoot 'bundle-build-command-final.txt') -Encoding utf8;$bundleOut=Join-Path $PacketRoot 'bundle-build-final.stdout.log';$bundleErr=Join-Path $PacketRoot 'bundle-build-final.stderr.log';$bundleProc=Start-Process -FilePath $pwsh -ArgumentList $bundleLine -WorkingDirectory $SourceRoot -NoNewWindow -Wait -PassThru -RedirectStandardOutput $bundleOut -RedirectStandardError $bundleErr;$bundleExit=$bundleProc.ExitCode;$bundleText=(Get-Content $bundleOut -Raw -ErrorAction SilentlyContinue)+(Get-Content $bundleErr -Raw -ErrorAction SilentlyContinue);$bundleText|Set-Content -LiteralPath (Join-Path $PacketRoot 'bundle-build-final.log') -Encoding utf8;"EXIT_CODE=$bundleExit"|Add-Content -LiteralPath (Join-Path $PacketRoot 'bundle-build-final.log') -Encoding utf8;if($bundleExit -ne 0){throw "Bundle build failed with exit $bundleExit"}
& git -C $SourceRoot diff --quiet;if($LASTEXITCODE -ne 0){throw 'Build changed tracked source.'};& git -C $SourceRoot diff --cached --quiet;if($LASTEXITCODE -ne 0){throw 'Build staged source changes.'}
$report=[ordered]@{sourceCommit=$commit;committedDeltaSha256=$patchHash;nodeVersion=$nodeVersion;npmVersion=$npmVersion;ambientEnvironmentClearedBeforeNpm=$true;npmUserConfig=$userConfig;npmGlobalConfig=$globalConfig;npmCache=$cache;npmCiExitCode=$ci;buildExitCode=$build;guiTypecheckExitCode=$typecheck;focusedTestsExitCode=$tests;npmPackExitCode=$pack;bundleBuildExitCode=$bundleExit;packagePath=$archive.FullName;packageBytes=$archive.Length;packageSha256=(Get-FileHash $archive.FullName -Algorithm SHA256).Hash.ToLowerInvariant();bundlePath=$bundle;bundleBytes=(Get-Item $bundle).Length;bundleSha256=(Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant();trackedSourceChangesAfterBuild=0;indexChangesAfterBuild=0}
$report|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $PacketRoot 'build-results-final.json') -Encoding utf8;$report|ConvertTo-Json -Depth 5
